// Feriados nacionais fixos (MM-DD) para a janela operacional. Réplica enxuta
// da lógica que já existe no RondaVirtual; se a data cair em fim de semana ou
// feriado, ou fora do horário comercial, libera o acionamento pela segurança.
const DIESEL_FERIADOS_FIXOS = ["01-01","04-21","05-01","09-07","10-12","11-02","11-15","11-20","12-25"];
function dieselEhFeriado(d){
  const mmdd = `${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
  return DIESEL_FERIADOS_FIXOS.includes(mmdd);
}
// Retorna a janela operacional atual: comercial (dia útil 8h-18h) x liberada.
function dieselJanelaAgora(){
  const d = new Date();
  const dow = d.getDay();               // 0=dom ... 6=sáb
  const h = d.getHours();
  const fimDeSemana = dow===0 || dow===6;
  const feriado = dieselEhFeriado(d);
  const comercial = !fimDeSemana && !feriado && h>=8 && h<18;
  if(comercial) return { tipo:"weekday_commercial", liberada:false, label:"☀️ Horário comercial — acionamento sob responsabilidade da Manutenção" };
  if(fimDeSemana || feriado) return { tipo:"weekend_holiday", liberada:true, label:(feriado?"🎌 Feriado":"📅 Fim de semana")+" — acionamento liberado para a segurança" };
  return { tipo:"night_shift", liberada:true, label:"🌙 Fora do horário comercial — acionamento liberado para a segurança" };
}
function dieselFmtDur(iniIso, fimMs){
  if(!iniIso) return "—";
  const diff = Math.max(0, (fimMs||Date.now()) - new Date(iniIso).getTime());
  const h=Math.floor(diff/3600000), m=Math.floor((diff%3600000)/60000), s=Math.floor((diff%60000)/1000);
  return `${String(h).padStart(2,"0")}:${String(m).padStart(2,"0")}:${String(s).padStart(2,"0")}`;
}
const MOKED_LOGO = "data:image/jpeg;base64,";

function newId(){ try { return crypto.randomUUID(); } catch { return "id-"+Date.now()+"-"+Math.random().toString(36).slice(2,8); } }
function pad2(n){ return String(n).padStart(2,"0"); }
function fmtDataHora(iso){ if(!iso) return "—"; try { const d=new Date(iso); return d.toLocaleDateString("pt-BR")+" "+d.toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"}); } catch { return "—"; } }
function fmtHora(iso){ if(!iso) return "—"; try { return new Date(iso).toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"}); } catch { return "—"; } }
// Hora "HH:MM" no fuso local a partir de um ISO (para pré-preencher inputs type=time)
function isoParaHoraLocal(iso){ try{ const d=iso?new Date(iso):new Date(); const h=String(d.getHours()).padStart(2,"0"); const m=String(d.getMinutes()).padStart(2,"0"); return `${h}:${m}`; }catch{ return ""; } }
// Combina a DATA de um ISO base (ou hoje) com uma hora "HH:MM" digitada, gerando
// novo ISO no fuso local — evita o bug de UTC de toISOString().split.
function horaLocalParaIso(horaHHMM, isoBase){
  try{
    if(!horaHHMM) return isoBase || new Date().toISOString();
    const base = isoBase ? new Date(isoBase) : new Date();
    const [h,m] = horaHHMM.split(":").map(n=>parseInt(n,10));
    if(Number.isNaN(h)||Number.isNaN(m)) return isoBase || new Date().toISOString();
    base.setHours(h, m, 0, 0);
    return base.toISOString();
  }catch{ return isoBase || new Date().toISOString(); }
}
function fmtDiaMes(iso){ if(!iso) return {d:"—",m:""}; try { const d=new Date(iso); return { d: pad2(d.getDate()), m: d.toLocaleDateString("pt-BR",{month:"short"}).replace(".","") }; } catch { return {d:"—",m:""}; } }
function turnoAgora(){ const h=new Date().getHours(); return (h>=6&&h<18) ? "Diurno" : "Noturno"; }
function duracaoFmt(msIni, msFim){
  const toMs = (x)=> x==null ? Date.now() : (typeof x==="number" ? x : (x instanceof Date ? x.getTime() : new Date(x).getTime()));
  const diff = Math.max(0, toMs(msFim)-toMs(msIni));
  const h = Math.floor(diff/3600000), m = Math.floor((diff%3600000)/60000);
  return `${h}h ${pad2(m)}min`;
}

async function loadEnergia(projectId){
  let data = null;
  try {
    const snap = await getDoc(doc(db,"energia_ocorrencias",projectId));
    if(snap.exists()){ data=snap.data(); try{localStorage.setItem(`energia_${projectId}`,JSON.stringify(data));}catch(e){} }
  } catch(e){}
  if(!data){ try{ const l=localStorage.getItem(`energia_${projectId}`); if(l) data=JSON.parse(l); }catch(e){} }
  data = data || {};
  return { config: data.config||{}, eventos: data.eventos||[] };
}
async function saveEnergia(projectId, data){
  const payload = { ...data, updatedAt:new Date().toISOString() };
  try { await setDoc(doc(db,"energia_ocorrencias",projectId), payload); } catch(e){ console.error("energia save:", e); }
  try { localStorage.setItem(`energia_${projectId}`, JSON.stringify(payload)); } catch(e){}
}

// ── Puxado pelo relatório semanal (App.jsx) — resumo dos últimos 7 dias
export async function loadEnergiaResumoParaPDF(projectId, diasJanela=7){
  const { eventos } = await loadEnergia(projectId);
  const corte = Date.now() - diasJanela*86400000;
  const doPeriodo = eventos.filter(e=>e.inicioQueda && new Date(e.inicioQueda).getTime()>=corte);
  const tempoTotalMs = doPeriodo.reduce((a,e)=>a+(e.fimQueda?(new Date(e.fimQueda)-new Date(e.inicioQueda)):0),0);
  return { quedas: doPeriodo.length, tempoTotalMs, eventos: doPeriodo };
}

function comprimirFoto(file){
  return new Promise((resolve)=>{
    try {
      const img = new Image();
      const url = URL.createObjectURL(file);
      img.onload = () => {
        try {
          const MAX=640; let w=img.width,h=img.height;
          const s=Math.min(1,MAX/Math.max(w,h));
          w=Math.max(1,Math.round(w*s)); h=Math.max(1,Math.round(h*s));
          const c=document.createElement("canvas"); c.width=w; c.height=h;
          c.getContext("2d").drawImage(img,0,0,w,h);
          URL.revokeObjectURL(url);
          resolve(c.toDataURL("image/jpeg",0.6));
        } catch(e){ resolve(null); }
      };
      img.onerror=()=>{URL.revokeObjectURL(url);resolve(null);};
      img.src=url;
    } catch(e){ resolve(null); }
  });
}

